static bool wifi_field_valid(const uint8_t *value, size_t length, size_t maximum, bool allow_empty)
{
    if (!value || length > maximum || (!allow_empty && length == 0U)) return false;
    for (size_t i = 0; i < length; ++i) {
        /* The SDK's AT tokenizer splits on commas even inside double quotes. */
        if (value[i] == '"' || value[i] == '\\' || value[i] == ',' || value[i] < 0x20 || value[i] == 0x7f)
            return false;
    }
    return true;
}

static OPERATE_RET wifi_execute(const char *command, char *reply, size_t reply_capacity, size_t *reply_length,
                                uint32_t timeout_ms)
{
    if (!command || !reply || reply_capacity < 2U) return OPRT_INVALID_PARM;
    if (vw553_device_negotiate(VW553_WIFI_COMMAND_TIMEOUT_MS) != OPRT_OK) return OPRT_COM_ERROR;
    vw553_uart_request_t request = {.command = command,
                                    .command_length = strlen(command),
                                    .reply = reply,
                                    .reply_capacity = reply_capacity,
                                    .reply_length = reply_length,
                                    .timeout_ms = timeout_ms};
    vw553_at_result_t result = VW553_AT_RESULT_NONE;
    int32_t status = vw553_device_execute(&request, &result);
    if (status != OPRT_OK) return status;
    return result == VW553_AT_RESULT_OK ? OPRT_OK : OPRT_COM_ERROR;
}

static OPERATE_RET wifi_command(const char *command)
{
    char reply[512];
    size_t reply_length = 0U;
    return wifi_execute(command, reply, sizeof(reply), &reply_length, VW553_WIFI_COMMAND_TIMEOUT_MS);
}

static void wifi_ps_policy_set(bool enabled, uint8_t dtim)
{
    taskENTER_CRITICAL();
    s_wifi_ps_enabled = enabled;
    s_wifi_ps_dtim = enabled ? dtim : 0U;
    if (!enabled) s_wifi_ps_applied = false;
    taskEXIT_CRITICAL();
}

static OPERATE_RET wifi_ps_apply(bool enabled, uint8_t dtim)
{
    char command[32];
    unsigned mode = enabled ? 2U : 0U;
    unsigned interval = enabled ? dtim : 0U;
    int written = snprintf(command, sizeof(command), "AT+TY553XPS=%u,%u", mode, interval);
    if (written < 0 || (size_t)written >= sizeof(command)) return OPRT_INVALID_PARM;
    OPERATE_RET status = wifi_command(command);
    if (status == OPRT_OK) {
        taskENTER_CRITICAL();
        s_wifi_ps_applied = enabled;
        s_wifi_ps_applied_known = true;
        s_wifi_ps_applied_dtim = enabled ? dtim : 0U;
        taskEXIT_CRITICAL();
    }
    VW553_SUMMARY("wifi ps %s dtim=%u status=%d", enabled ? "on" : "off", interval, status);
    return status;
}

static OPERATE_RET wifi_ps_force_awake(void)
{
    /* Entering STA mode re-enables traffic-based PS inside the vendor stack, so
     * every association attempt must explicitly override that default. */
    return wifi_ps_apply(false, 0U);
}

static void wifi_ps_restore(void)
{
    bool enabled = false;
    bool applied = false;
    bool known = false;
    uint8_t dtim = 0U;
    uint8_t applied_dtim = 0U;
    taskENTER_CRITICAL();
    enabled = s_wifi_ps_enabled;
    dtim = s_wifi_ps_dtim;
    applied = s_wifi_ps_applied;
    known = s_wifi_ps_applied_known;
    applied_dtim = s_wifi_ps_applied_dtim;
    taskEXIT_CRITICAL();
    if (known && applied == enabled && (!enabled || applied_dtim == dtim)) return;
    OPERATE_RET status = wifi_ps_apply(enabled, dtim);
    if (status != OPRT_OK)
        VW553_SUMMARY("wifi ps restore failed enable=%d dtim=%u status=%d", enabled ? 1 : 0, dtim, status);
}

static bool parse_mac(const char *text, uint8_t mac[MAC_ADDR_LEN])
{
    unsigned int octets[MAC_ADDR_LEN];
    while (*text == ' ' || *text == '\t') ++text;
    if (*text == '"') ++text;
    if (sscanf(text, "%2x:%2x:%2x:%2x:%2x:%2x", &octets[0], &octets[1], &octets[2], &octets[3],
               &octets[4], &octets[5]) != MAC_ADDR_LEN) return false;
    for (size_t i = 0; i < MAC_ADDR_LEN; ++i) mac[i] = (uint8_t)octets[i];
    return true;
}

static bool parse_ipv4_field(const char *line, const char *prefix, char output[16])
{
    size_t prefix_len = strlen(prefix);
    if (strncmp(line, prefix, prefix_len) != 0) return false;
    const char *value = line + prefix_len;
    if (*value == '"') ++value;
    size_t length = strcspn(value, "\"\r\n");
    if (!length || length >= 16U) return false;
    int a, b, c, d, consumed = 0;
    if (sscanf(value, "%d.%d.%d.%d%n", &a, &b, &c, &d, &consumed) != 4 || (size_t)consumed != length ||
        a < 0 || a > 255 || b < 0 || b > 255 || c < 0 || c > 255 || d < 0 || d > 255) return false;
    memcpy(output, value, length);
    output[length] = '\0';
    return true;
}

static void wifi_event_line(void *context, const vw553_device_event_t *event)
{
    (void)context;
    if (!event) return;
    if (event->kind == VW553_DEVICE_EVENT_RESET) {
        WF_STATION_STAT_E previous;
        taskENTER_CRITICAL();
        previous = s_wifi_station_status;
        s_wifi_station_status = WSS_IDLE;
        memset(&s_ap_ip, 0, sizeof(s_ap_ip));
        s_ap_ip_valid = false;
        taskEXIT_CRITICAL();
        s_wifi_ps_applied = false;
        s_wifi_ps_applied_known = false;
        VW553_LOG("device reset invalidated Wi-Fi state previous=%d", (int)previous);
        if (previous == WSS_GOT_IP || previous == WSS_CONN_SUCCESS) wifi_notify(WFE_DISCONNECTED);
        return;
    }
    if (event->kind != VW553_DEVICE_EVENT_LINE) return;
    const char *line = event->value.line.text;
    size_t length = event->value.line.length;
    taskENTER_CRITICAL();
    if (length == sizeof("WIFI CONNECTED") - 1U && memcmp(line, "WIFI CONNECTED", length) == 0) {
        if (s_wifi_station_status == WSS_CONNECTING) s_wifi_station_status = WSS_CONN_SUCCESS;
    }
    taskEXIT_CRITICAL();
}

