static OPERATE_RET wifi_ensure_initialized(void)
{
    if (!s_wifi_subscribed) {
        int32_t status = vw553_device_subscribe(wifi_event_line, NULL);
        if (status != OPRT_OK) return status;
        s_wifi_subscribed = true;
    }
    return vw553_device_negotiate(VW553_WIFI_COMMAND_TIMEOUT_MS);
}

static bool wifi_parse_cipsta(const char *reply, NW_IP_S *ip)
{
    char line[96];
    char values[3][16] = {{0}};
    size_t found = 0U;
    const char *cursor = reply;
    while (*cursor) {
        size_t length = strcspn(cursor, "\r\n");
        if (length && length < sizeof(line)) {
            memcpy(line, cursor, length);
            line[length] = '\0';
            if (strncmp(line, "+CIPSTA: ", 9U) == 0 && found < 3U &&
                parse_ipv4_field(line, "+CIPSTA: ", values[found])) ++found;
        }
        cursor += length;
        while (*cursor == '\r' || *cursor == '\n') ++cursor;
    }
    if (found != 3U) return false;
    memset(ip, 0, sizeof(*ip));
    memcpy(ip->ip, values[0], sizeof(values[0]));
    memcpy(ip->mask, values[1], sizeof(values[1]));
    memcpy(ip->gw, values[2], sizeof(values[2]));
    ip->dhcpen = TRUE;
    return true;
}

static bool wifi_nonzero_ip(const NW_IP_S *ip)
{
    return ip->ip[0] && strcmp(ip->ip, "0.0.0.0") != 0;
}

