/**
 * @brief get wifi ip info.when wifi works in
 *        ap+station mode, wifi has two ips.
 *
 * @param[in]       wf          wifi function type
 * @param[out]      ip          the ip addr info
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_wifi_get_ip(const WF_IF_E wf, NW_IP_S *ip)
{
    // --- BEGIN: user implements ---
    if (!ip || (wf != WF_STATION && wf != WF_AP)) return OPRT_INVALID_PARM;
    if (wf == WF_STATION && s_wifi_join_active) return OPRT_COM_ERROR;
    if (wf == WF_AP && wifi_ap_ip_cache_load(ip)) return OPRT_OK;
    if (wf == WF_STATION && vw553_socket_backend_has_active_socket() && wifi_station_ip_cache_load(ip)) return OPRT_OK;
    char reply[1024];
    size_t reply_length = 0U;
    const char *command = wf == WF_STATION ? "AT+CIPSTA?" : "AT+CIPAP?";
    OPERATE_RET status = wifi_execute(command, reply, sizeof(reply), &reply_length, VW553_WIFI_COMMAND_TIMEOUT_MS);
    if (status != OPRT_OK) return status;
    if (wf == WF_STATION) {
        if (!wifi_parse_cipsta(reply, ip) || !wifi_nonzero_ip(ip)) return OPRT_COM_ERROR;
        wifi_station_ip_cache_store(ip);
        return OPRT_OK;
    }
    memset(ip, 0, sizeof(*ip));
    const char *cursor = reply;
    while (*cursor) {
        size_t line_len = strcspn(cursor, "\r\n");
        if (line_len && line_len < 96U) {
            char line[96];
            memcpy(line, cursor, line_len); line[line_len] = '\0';
            (void)parse_ipv4_field(line, "+CIPAP:ip:\"", ip->ip);
            (void)parse_ipv4_field(line, "+CIPAP:netmask:\"", ip->mask);
            (void)parse_ipv4_field(line, "+CIPAP:gateway:\"", ip->gw);
        }
        cursor += line_len; while (*cursor == '\r' || *cursor == '\n') ++cursor;
    }
    ip->dhcpen = TRUE;
    if (!wifi_nonzero_ip(ip)) return OPRT_COM_ERROR;
    wifi_ap_ip_cache_store(ip);
    return OPRT_OK;
    // --- END: user implements ---
}

