/**
 * @brief wifi set ip
 *
 * @param[in]       wf     wifi function type
 * @param[in]       ip     the ip addr info
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_wifi_set_ip(const WF_IF_E wf, NW_IP_S *ip)
{
    // --- BEGIN: user implements ---
    if (!ip || (wf != WF_STATION && wf != WF_AP) || !ip->ip[0] || !ip->mask[0] || !ip->gw[0])
        return OPRT_INVALID_PARM;
    if (ip->dhcpen) return OPRT_NOT_SUPPORTED;
    if (!wifi_field_valid((const uint8_t *)ip->ip, strnlen(ip->ip, sizeof(ip->ip)), 15U, false) ||
        !wifi_field_valid((const uint8_t *)ip->mask, strnlen(ip->mask, sizeof(ip->mask)), 15U, false) ||
        !wifi_field_valid((const uint8_t *)ip->gw, strnlen(ip->gw, sizeof(ip->gw)), 15U, false))
        return OPRT_INVALID_PARM;
    char command[128];
    int written;
    if (wf == WF_STATION) {
        /* Original AT+CIPSTA setter order is ip, netmask, gateway. */
        written = snprintf(command, sizeof(command), "AT+CIPSTA=\"%s\",\"%s\",\"%s\"", ip->ip, ip->mask,
                           ip->gw);
    } else {
        /* Original AT+CIPAP setter order is ip, gateway, netmask. */
        written = snprintf(command, sizeof(command), "AT+CIPAP=\"%s\",\"%s\",\"%s\"", ip->ip, ip->gw,
                           ip->mask);
    }
    if (written < 0 || (size_t)written >= sizeof(command)) return OPRT_INVALID_PARM;
    OPERATE_RET status = wifi_command(command);
    if (status == OPRT_OK && wf == WF_AP) wifi_ap_ip_cache_store(ip);
    return status;
    // --- END: user implements ---
}

