/**
 * @brief get wifi mac info.when wifi works in
 *        ap+station mode, wifi has two macs.
 *
 * @param[in]       wf          wifi function type
 * @param[out]      mac         the mac info
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_wifi_get_mac(const WF_IF_E wf, NW_MAC_S *mac)
{
    // --- BEGIN: user implements ---
    if (!mac || (wf != WF_STATION && wf != WF_AP)) return OPRT_INVALID_PARM;
    char reply[512];
    size_t reply_length = 0U;
    OPERATE_RET status = wifi_execute("AT+CIFSR", reply, sizeof(reply), &reply_length, VW553_WIFI_COMMAND_TIMEOUT_MS);
    if (status != OPRT_OK) return status;
    /* Without station+AP concurrency, the vendor AP start reuses VIF 0 and
     * its base MAC. The caller requests this before the AP is brought up. */
    const char *key = wf == WF_STATION ? "+CIFSR:STAMAC," : "+CIFSR:APMAC,";
    const char *line = strstr(reply, key);
    bool fallback_sta_mac = false;
    if (!line && wf == WF_AP) { line = strstr(reply, "+CIFSR:STAMAC,"); fallback_sta_mac = line != NULL; }
    if (!line) return OPRT_COM_ERROR;
    line += strlen(fallback_sta_mac ? "+CIFSR:STAMAC," : key);
    return parse_mac(line, mac->mac) ? OPRT_OK : OPRT_COM_ERROR;
    // --- END: user implements ---
}

/**
 * @brief set wifi work mode
 *
 * @param[in]       mode        wifi work mode
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_wifi_set_work_mode(const WF_WK_MD_E mode)
{
    // --- BEGIN: user implements ---
    if (mode == WWM_SOFTAP) { s_wifi_work_mode = mode; return OPRT_OK; }
    if (mode == WWM_STATION) {
        /* Keep the original explicit mode transition. It is intentionally sent
         * even when cached state already says STA: after SoftAP provisioning it
         * gives VW553 another synchronization point before LAN/TCP sockets start. */
        OPERATE_RET status = wifi_switch_to_station();
        if (status == OPRT_OK) s_wifi_work_mode = mode;
        return status;
    }
    if (mode == WWM_POWERDOWN) return OPRT_NOT_SUPPORTED;
    return OPRT_NOT_SUPPORTED;
    // --- END: user implements ---
}

/**
 * @brief get wifi work mode
 *
 * @param[out]      mode        wifi work mode
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_wifi_get_work_mode(WF_WK_MD_E *mode)
{
    // --- BEGIN: user implements ---
    if (!mode) return OPRT_INVALID_PARM;
    char reply[256];
    size_t reply_length = 0U;
    OPERATE_RET status = wifi_execute("AT+CWMODE_CUR?", reply, sizeof(reply), &reply_length,
                                      VW553_WIFI_COMMAND_TIMEOUT_MS);
    if (status != OPRT_OK) return status;
    char *entry = strstr(reply, "+CWMODE_CUR:");
    int value = -1;
    if (!entry || sscanf(entry, "+CWMODE_CUR:%d", &value) != 1) return OPRT_COM_ERROR;
    if (value == 1) *mode = WWM_STATION;
    else if (value == 2) *mode = WWM_SOFTAP;
    else return OPRT_NOT_SUPPORTED;
    s_wifi_work_mode = *mode;
    return OPRT_OK;
    // --- END: user implements ---
}

